//! Default hasher for [`crate::hopscotch::HopscotchMap`].
//!
//! `tsl::hopscotch_map` defaults to `std::hash`, which for integers is the
//! identity function. Rust's `std` only ships `RandomState` (SipHash-1-3) as a
//! ready-made `BuildHasher`, and it is randomly seeded per process. We instead
//! implement FNV-1a from scratch: it is deterministic, cheap for the small keys
//! a hopscotch table is tuned for, and avoids pulling in any external crate.

use std::hash::{BuildHasher, Hasher};

const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

/// FNV-1a, 64-bit.
#[derive(Clone, Copy, Debug)]
pub struct FnvHasher(u64);

impl Default for FnvHasher {
    fn default() -> Self {
        FnvHasher(FNV_OFFSET_BASIS)
    }
}

impl Hasher for FnvHasher {
    fn write(&mut self, bytes: &[u8]) {
        let mut hash = self.0;
        for &byte in bytes {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(FNV_PRIME);
        }
        self.0 = hash;
    }

    fn finish(&self) -> u64 {
        // FNV-1a alone leaves too little entropy in the low bits, and the table
        // masks with `bucket_count - 1` (a power of two) to pick a home bucket.
        // Mix the high bits down first (the xor-shift finalizer from splitmix64).
        let mut hash = self.0;
        hash ^= hash >> 33;
        hash = hash.wrapping_mul(0xff51_afd7_ed55_8ccd);
        hash ^= hash >> 33;
        hash
    }
}

/// [`BuildHasher`] producing [`FnvHasher`]s.
#[derive(Clone, Copy, Debug, Default)]
pub struct FnvBuildHasher;

impl BuildHasher for FnvBuildHasher {
    type Hasher = FnvHasher;

    fn build_hasher(&self) -> FnvHasher {
        FnvHasher::default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;
    use std::hash::Hash;

    fn hash_of<T: Hash>(value: &T) -> u64 {
        let mut hasher = FnvBuildHasher.build_hasher();
        value.hash(&mut hasher);
        hasher.finish()
    }

    #[test]
    fn deterministic_across_builders() {
        assert_eq!(hash_of(&42i32), hash_of(&42i32));
        assert_ne!(hash_of(&42i32), hash_of(&43i32));
    }

    #[test]
    fn low_bits_are_well_distributed() {
        // Sequential integers must not collide once masked to a small table.
        let masked: HashSet<u64> = (0..64i32).map(|i| hash_of(&i) & 1023).collect();
        assert!(masked.len() >= 60, "poor low-bit spread: {}", masked.len());
    }
}

