//! Storage element of the hopscotch table.

/// Number of slots in a bucket's neighborhood, i.e. the maximum distance an
/// entry may live from its home bucket. `tsl::hopscotch_map` defaults to 62 so
/// the neighborhood bitmap fits in a single `u64`; we keep that.
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// One slot of the table.
///
/// `neighborhood` is a bitmap owned by this bucket *as a home bucket*: bit `i`
/// is set when the entry stored `i` slots further along belongs here. The
/// `entry` field is independent — it may hold an entry homed at an earlier
/// bucket.
pub struct Bucket<K, V> {
    neighborhood: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    pub fn new() -> Self {
        Bucket {
            neighborhood: 0,
            entry: None,
        }
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.entry.is_none()
    }

    #[inline]
    pub fn entry(&self) -> Option<&(K, V)> {
        self.entry.as_ref()
    }

    #[inline]
    pub fn entry_mut(&mut self) -> Option<&mut (K, V)> {
        self.entry.as_mut()
    }

    #[inline]
    pub fn set_entry(&mut self, entry: (K, V)) {
        debug_assert!(self.entry.is_none());
        self.entry = Some(entry);
    }

    #[inline]
    pub fn take_entry(&mut self) -> Option<(K, V)> {
        self.entry.take()
    }

    #[inline]
    pub fn neighborhood(&self) -> u64 {
        self.neighborhood
    }

    /// Marks the slot `offset` positions after this bucket as holding one of
    /// our entries.
    #[inline]
    pub fn set_neighbor(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        self.neighborhood |= 1u64 << offset;
    }

    #[inline]
    pub fn clear_neighbor(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        self.neighborhood &= !(1u64 << offset);
    }

    #[inline]
    pub fn has_neighbor(&self, offset: usize) -> bool {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        self.neighborhood & (1u64 << offset) != 0
    }

    #[inline]
    pub fn clear(&mut self) {
        self.neighborhood = 0;
        self.entry = None;
    }
}

impl<K, V> Default for Bucket<K, V> {
    fn default() -> Self {
        Bucket::new()
    }
}

/// Iterator over the offsets set in a neighborhood bitmap, ascending.
pub struct NeighborOffsets(u64);

impl NeighborOffsets {
    #[inline]
    pub fn new(neighborhood: u64) -> Self {
        NeighborOffsets(neighborhood)
    }
}

impl Iterator for NeighborOffsets {
    type Item = usize;

    #[inline]
    fn next(&mut self) -> Option<usize> {
        if self.0 == 0 {
            return None;
        }
        let offset = self.0.trailing_zeros() as usize;
        self.0 &= self.0 - 1; // clear lowest set bit
        Some(offset)
    }
}

