//! Hopscotch hashing.
//!
//! A hopscotch table keeps every entry within a fixed-size *neighborhood* of
//! its home bucket, so a lookup only ever probes at most `NEIGHBORHOOD_SIZE`
//! slots — and in practice only the slots flagged in the home bucket's bitmap.
//! On insertion, if the nearest free slot is too far away, the table "hops" it
//! backwards by displacing entries that can tolerate being moved, until the
//! free slot lands inside the neighborhood.

pub mod bucket;
pub mod map;

pub use bucket::NEIGHBORHOOD_SIZE;
pub use map::{HopscotchMap, Iter, Keys, Values};

