//! A hash map using hopscotch hashing, mirroring the subset of the
//! `tsl::hopscotch_map` interface used by the ported test.

use std::borrow::Borrow;
use std::fmt;
use std::hash::{BuildHasher, Hash, Hasher};
use std::iter::FromIterator;

use super::bucket::{Bucket, NeighborOffsets, NEIGHBORHOOD_SIZE};
use crate::hash::FnvBuildHasher;

/// Bucket count used by the first allocation. Always a power of two so the
/// home bucket can be selected with a mask instead of a division.
const INITIAL_BUCKET_COUNT: usize = 16;

/// Default maximum load factor, matching `tsl::hopscotch_map`'s default.
const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.95;

pub struct HopscotchMap<K, V, S = FnvBuildHasher> {
    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots: the trailing slots let a
    /// bucket near the end own a full neighborhood without wrapping around,
    /// which keeps every probe a straight forward scan.
    buckets: Vec<Bucket<K, V>>,
    bucket_count: usize,
    len: usize,
    max_load_factor: f32,
    load_threshold: usize,
    hasher: S,
}

impl<K, V> HopscotchMap<K, V, FnvBuildHasher> {
    /// Creates an empty map. No allocation happens until the first insert.
    pub fn new() -> Self {
        Self::with_hasher(FnvBuildHasher)
    }

    /// Creates an empty map sized to hold `capacity` elements without rehashing.
    pub fn with_capacity(capacity: usize) -> Self {
        Self::with_capacity_and_hasher(capacity, FnvBuildHasher)
    }
}

impl<K, V, S> HopscotchMap<K, V, S> {
    pub fn with_hasher(hasher: S) -> Self {
        HopscotchMap {
            buckets: Vec::new(),
            bucket_count: 0,
            len: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            load_threshold: 0,
            hasher,
        }
    }

    /// Number of elements stored. Equivalent to `tsl::hopscotch_map::size()`.
    #[inline]
    pub fn len(&self) -> usize {
        self.len
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Number of home buckets, i.e. `bucket_count()` in the C++ interface.
    #[inline]
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.len as f32 / self.bucket_count as f32
        }
    }

    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    /// Removes every element, keeping the allocated buckets.
    pub fn clear(&mut self) {
        for bucket in self.buckets.iter_mut() {
            bucket.clear();
        }
        self.len = 0;
    }

    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter {
            inner: self.buckets.iter(),
            remaining: self.len,
        }
    }

    pub fn keys(&self) -> Keys<'_, K, V> {
        Keys { inner: self.iter() }
    }

    pub fn values(&self) -> Values<'_, K, V> {
        Values { inner: self.iter() }
    }

    fn threshold(bucket_count: usize, max_load_factor: f32) -> usize {
        if bucket_count == 0 {
            0
        } else {
            // At least one slot must stay usable, otherwise a table could grow
            // forever without ever accepting an element.
            ((bucket_count as f64) * (max_load_factor as f64)) as usize.max(1)
        }
    }

    fn allocate(bucket_count: usize) -> Vec<Bucket<K, V>> {
        let total = bucket_count + NEIGHBORHOOD_SIZE - 1;
        let mut buckets = Vec::with_capacity(total);
        buckets.resize_with(total, Bucket::new);
        buckets
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    pub fn with_capacity_and_hasher(capacity: usize, hasher: S) -> Self {
        let mut map = Self::with_hasher(hasher);
        map.reserve(capacity);
        map
    }

    /// Grows the table so `capacity` elements fit without a rehash.
    pub fn reserve(&mut self, capacity: usize) {
        if capacity == 0 || capacity <= self.load_threshold {
            return;
        }
        let needed = ((capacity as f64) / (self.max_load_factor as f64)).ceil() as usize;
        self.rehash_to(needed.max(INITIAL_BUCKET_COUNT));
    }

    /// Inserts `key`/`value` if `key` is not already present.
    ///
    /// Returns `true` when the element was inserted. Like
    /// `std::unordered_map::insert` (and unlike `HashMap::insert`), an existing
    /// value is *not* overwritten.
    pub fn insert(&mut self, key: K, value: V) -> bool {
        if self.find_slot(&key).is_some() {
            return false;
        }
        self.insert_new(key, value);
        true
    }

    /// Inserts or overwrites, returning the previous value if there was one.
    /// Equivalent to `insert_or_assign` in the C++ interface.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        if let Some((home, offset)) = self.find_slot(&key) {
            let entry = self.buckets[home + offset]
                .entry_mut()
                .expect("bitmap and storage out of sync");
            return Some(std::mem::replace(&mut entry.1, value));
        }
        self.insert_new(key, value);
        None
    }

    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let (home, offset) = self.find_slot(key)?;
        self.buckets[home + offset].entry().map(|(_, v)| v)
    }

    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let (home, offset) = self.find_slot(key)?;
        self.buckets[home + offset].entry_mut().map(|(_, v)| v)
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.find_slot(key).is_some()
    }

    /// Erases `key`, returning the number of elements removed (0 or 1).
    ///
    /// This is the `tsl::hopscotch_map::erase(const key_type&)` overload; use
    /// [`HopscotchMap::remove`] when the removed value is wanted.
    pub fn erase<Q>(&mut self, key: &Q) -> usize
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        usize::from(self.remove_entry(key).is_some())
    }

    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.remove_entry(key).map(|(_, v)| v)
    }

    pub fn remove_entry<Q>(&mut self, key: &Q) -> Option<(K, V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let (home, offset) = self.find_slot(key)?;
        let entry = self.buckets[home + offset]
            .take_entry()
            .expect("bitmap and storage out of sync");
        self.buckets[home].clear_neighbor(offset);
        self.len -= 1;
        Some(entry)
    }

    fn hash_of<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        let mut hasher = self.hasher.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    #[inline]
    fn home_of(&self, hash: u64) -> usize {
        // bucket_count is a power of two, so masking replaces a modulo.
        (hash as usize) & (self.bucket_count - 1)
    }

    /// Locates `key` as `(home bucket, offset within its neighborhood)`.
    ///
    /// Only the slots flagged in the home bucket's bitmap are examined, so a
    /// miss usually touches a single cache line.
    fn find_slot<Q>(&self, key: &Q) -> Option<(usize, usize)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }
        let home = self.home_of(self.hash_of(key));
        for offset in NeighborOffsets::new(self.buckets[home].neighborhood()) {
            if let Some((k, _)) = self.buckets[home + offset].entry() {
                if k.borrow() == key {
                    return Some((home, offset));
                }
            }
        }
        None
    }

    /// Inserts a key already known to be absent, growing as needed.
    fn insert_new(&mut self, key: K, value: V) {
        if self.len + 1 > self.load_threshold {
            self.grow();
        }
        let mut entry = (key, value);
        loop {
            match self.try_place(entry) {
                Ok(()) => {
                    self.len += 1;
                    return;
                }
                Err(rejected) => {
                    // No free slot reachable from the home bucket: the only fix
                    // is a bigger table.
                    entry = rejected;
                    self.grow();
                }
            }
        }
    }

    /// Places an entry in its home neighborhood, hopping a free slot backwards
    /// when the nearest one is out of range.
    ///
    /// Returns the entry untouched if placement is impossible in this table.
    fn try_place(&mut self, entry: (K, V)) -> Result<(), (K, V)> {
        debug_assert!(self.bucket_count > 0);
        let home = self.home_of(self.hash_of(&entry.0));

        let mut free = match self.buckets[home..].iter().position(Bucket::is_empty) {
            Some(offset) => home + offset,
            None => return Err(entry),
        };

        while free - home >= NEIGHBORHOOD_SIZE {
            match self.hop_back(free) {
                Some(closer) => free = closer,
                None => return Err(entry),
            }
        }

        let offset = free - home;
        self.buckets[free].set_entry(entry);
        self.buckets[home].set_neighbor(offset);
        Ok(())
    }

    /// Moves the free slot at `free` closer to the start of the table by
    /// displacing an entry that can still reach `free` from its own home.
    ///
    /// Candidates are tried farthest-first so the free slot travels as far back
    /// as possible per hop. Returns the new free slot, or `None` if nothing can
    /// be displaced.
    fn hop_back(&mut self, free: usize) -> Option<usize> {
        let first_candidate = free.saturating_sub(NEIGHBORHOOD_SIZE - 1);
        for candidate in first_candidate..free {
            let distance = free - candidate;
            // Entries closer to `candidate` than `free` is: those can be moved
            // to `free` and still sit inside `candidate`'s neighborhood.
            let movable = self.buckets[candidate].neighborhood() & ((1u64 << distance) - 1);
            if movable == 0 {
                continue;
            }
            let offset = movable.trailing_zeros() as usize;
            let source = candidate + offset;

            let entry = self.buckets[source]
                .take_entry()
                .expect("bitmap and storage out of sync");
            self.buckets[free].set_entry(entry);
            self.buckets[candidate].clear_neighbor(offset);
            self.buckets[candidate].set_neighbor(distance);
            return Some(source);
        }
        None
    }

    fn grow(&mut self) {
        let target = if self.bucket_count == 0 {
            INITIAL_BUCKET_COUNT
        } else {
            self.bucket_count * 2
        };
        self.rehash_to(target);
    }

    /// Rebuilds the table with at least `requested` home buckets, doubling
    /// further if hopscotch placement fails for the current size.
    fn rehash_to(&mut self, requested: usize) {
        let mut entries: Vec<(K, V)> = Vec::with_capacity(self.len);
        for bucket in self.buckets.iter_mut() {
            if let Some(entry) = bucket.take_entry() {
                entries.push(entry);
            }
        }

        let mut bucket_count = requested.next_power_of_two().max(INITIAL_BUCKET_COUNT);
        loop {
            self.buckets = Self::allocate(bucket_count);
            self.bucket_count = bucket_count;
            self.load_threshold = Self::threshold(bucket_count, self.max_load_factor);

            let mut pending = entries.into_iter();
            let mut rejected = None;
            for entry in pending.by_ref() {
                if let Err(entry) = self.try_place(entry) {
                    rejected = Some(entry);
                    break;
                }
            }

            let rejected = match rejected {
                None => return,
                Some(entry) => entry,
            };

            // Reclaim what was already re-placed and try again, twice as large.
            let leftover: Vec<(K, V)> = pending.collect();
            entries = Vec::with_capacity(self.len);
            for bucket in self.buckets.iter_mut() {
                if let Some(entry) = bucket.take_entry() {
                    entries.push(entry);
                }
            }
            entries.push(rejected);
            entries.extend(leftover);
            bucket_count *= 2;
        }
    }
}

impl<K, V> Default for HopscotchMap<K, V, FnvBuildHasher> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V, S> fmt::Debug for HopscotchMap<K, V, S>
where
    K: fmt::Debug,
    V: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter()).finish()
    }
}

impl<K, V> FromIterator<(K, V)> for HopscotchMap<K, V, FnvBuildHasher>
where
    K: Hash + Eq,
{
    fn from_iter<I: IntoIterator<Item = (K, V)>>(iter: I) -> Self {
        let iter = iter.into_iter();
        let mut map = HopscotchMap::with_capacity(iter.size_hint().0);
        for (k, v) in iter {
            map.insert_or_assign(k, v);
        }
        map
    }
}

impl<'a, K, V, S> IntoIterator for &'a HopscotchMap<K, V, S> {
    type Item = (&'a K, &'a V);
    type IntoIter = Iter<'a, K, V>;

    fn into_iter(self) -> Iter<'a, K, V> {
        self.iter()
    }
}

/// Iterator over the map's entries, in unspecified order.
pub struct Iter<'a, K, V> {
    inner: std::slice::Iter<'a, Bucket<K, V>>,
    remaining: usize,
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<(&'a K, &'a V)> {
        for bucket in self.inner.by_ref() {
            if let Some((k, v)) = bucket.entry() {
                self.remaining -= 1;
                return Some((k, v));
            }
        }
        None
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<'a, K, V> ExactSizeIterator for Iter<'a, K, V> {}

pub struct Keys<'a, K, V> {
    inner: Iter<'a, K, V>,
}

impl<'a, K, V> Iterator for Keys<'a, K, V> {
    type Item = &'a K;

    fn next(&mut self) -> Option<&'a K> {
        self.inner.next().map(|(k, _)| k)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        self.inner.size_hint()
    }
}

pub struct Values<'a, K, V> {
    inner: Iter<'a, K, V>,
}

impl<'a, K, V> Iterator for Values<'a, K, V> {
    type Item = &'a V;

    fn next(&mut self) -> Option<&'a V> {
        self.inner.next().map(|(_, v)| v)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        self.inner.size_hint()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    #[test]
    fn matches_the_ported_test_for_small_counts() {
        for count in 0..64 {
            let mut map = HopscotchMap::new();
            for i in 0..count {
                map.insert(i, i * 2);
            }
            let mut removed = 0;
            let mut i = 0;
            while i < count {
                removed += map.erase(&i);
                i += 2;
            }
            let expected_removed = (count + 1) / 2;
            assert_eq!(removed, expected_removed as usize);
            assert_eq!(map.len(), (count - expected_removed) as usize);
        }
    }

    #[test]
    fn insert_does_not_overwrite() {
        let mut map = HopscotchMap::new();
        assert!(map.insert("k", 1));
        assert!(!map.insert("k", 2));
        assert_eq!(map.get("k"), Some(&1));
        assert_eq!(map.insert_or_assign("k", 3), Some(1));
        assert_eq!(map.get("k"), Some(&3));
        assert_eq!(map.len(), 1);
    }

    #[test]
    fn behaves_like_std_hashmap_under_mixed_traffic() {
        let mut mine = HopscotchMap::new();
        let mut reference: HashMap<u64, u64> = HashMap::new();

        // Deterministic pseudo-random traffic (xorshift64) with clustered keys,
        // which is the pattern hopscotch's displacement logic has to survive.
        let mut state = 0x2545_f491_4f6c_dd1du64;
        let mut next = move || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };

        for step in 0..20_000u64 {
            let key = next() % 500;
            if step % 3 == 2 {
                assert_eq!(mine.erase(&key), usize::from(reference.remove(&key).is_some()));
            } else {
                let inserted = mine.insert(key, step);
                let already = reference.contains_key(&key);
                if !already {
                    reference.insert(key, step);
                }
                assert_eq!(inserted, !already);
            }
            assert_eq!(mine.len(), reference.len());
        }

        for (k, v) in &reference {
            assert_eq!(mine.get(k), Some(v));
        }
        for (k, v) in mine.iter() {
            assert_eq!(reference.get(k), Some(v));
        }
    }

    #[test]
    fn survives_pathological_collisions() {
        // Every key hashes to the same home bucket family: forces hopping,
        // rejection and growth paths.
        #[derive(PartialEq, Eq, Debug)]
        struct Clashing(u32);
        impl Hash for Clashing {
            fn hash<H: Hasher>(&self, state: &mut H) {
                state.write_u8(0);
            }
        }

        let mut map = HopscotchMap::new();
        for i in 0..200 {
            assert!(map.insert(Clashing(i), i));
        }
        assert_eq!(map.len(), 200);
        for i in 0..200 {
            assert_eq!(map.get(&Clashing(i)), Some(&i));
        }
        for i in 0..200 {
            assert_eq!(map.erase(&Clashing(i)), 1);
            assert_eq!(map.erase(&Clashing(i)), 0);
        }
        assert!(map.is_empty());
    }

    #[test]
    fn reserve_avoids_rehash_and_keeps_contents() {
        let mut map = HopscotchMap::with_capacity(1000);
        let buckets = map.bucket_count();
        for i in 0..1000 {
            map.insert(i, i);
        }
        assert_eq!(map.bucket_count(), buckets);
        assert_eq!(map.len(), 1000);
        assert!(map.load_factor() <= map.max_load_factor());

        map.clear();
        assert_eq!(map.len(), 0);
        assert_eq!(map.get(&5), None);
    }
}

