    ///
    /// Returns the entry untouched if placement is impossible in this table.
    fn try_place(&mut self, entry: (K, V)) -> Result<(), (K, V)> {
        debug_assert!(self.bucket_count > 0);
        let home = self.home_of(self.hash_of(&entry.0));

        let mut free = match self.buckets[home..].iter().position(Bucket::is_empty) {
            Some(offset) => home + offset,
            None => return Err(entry),
        };

        while free - home >= NEIGHBORHOOD_SIZE {
            match self.hop_back(free) {
                Some(closer) => free = closer,
