//! Emulation of libstdc++'s response to an exception that escapes `main`.

use std::io::Write;

/// Reproduces `std::terminate`'s verbose handler and aborts.
///
/// libstdc++ prints
///
/// ```text
/// terminate called after throwing an instance of 'std::invalid_argument'
///   what():  stoi
/// ```
///
/// to stderr and raises `SIGABRT`, which a shell reports as exit status 134.
/// [`std::process::abort`] raises the same signal, so the exit status matches
/// without any special casing.
pub fn terminate_with(exception_type: &str, what: &str) -> ! {
    let stderr = std::io::stderr();
    let mut stderr = stderr.lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of '{exception_type}'"
    );
    let _ = writeln!(stderr, "  what():  {what}");
    let _ = stderr.flush();
    std::process::abort();
}

