//! `std::stoi`, faithfully.
//!
//! Rust's `str::parse::<i32>()` is far stricter than `std::stoi`: it rejects
//! leading whitespace and any trailing garbage. `std::stoi` is defined in terms
//! of `strtol`, which skips whitespace, accepts an optional sign, consumes as
//! many base-10 digits as it can and simply stops at the first character that
//! does not fit. `"12abc"` is 12; `"3.9"` is 3; `"0x10"` is 0 (base 10 gives
//! `x` no special meaning); `"abc"` throws.

use std::fmt;

/// The two exceptions `std::stoi` can throw.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StoiError {
    /// `std::invalid_argument` — no digits could be consumed.
    InvalidArgument,
    /// `std::out_of_range` — the value does not fit in an `int`.
    OutOfRange,
}

impl StoiError {
    /// Name of the corresponding C++ exception type.
    pub fn exception_type(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// libstdc++ uses the function name as `what()` for both.
    pub fn what(self) -> &'static str {
        "stoi"
    }
}

impl fmt::Display for StoiError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.exception_type(), self.what())
    }
}

impl std::error::Error for StoiError {}

/// True for the characters C's `isspace` accepts in the default locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Equivalent of `std::stoi(str)`.
pub fn stoi(s: &str) -> Result<i32, StoiError> {
    stoi_with_pos(s).map(|(value, _)| value)
}

/// Equivalent of `std::stoi(str, &pos)`: also reports how many bytes were
/// consumed, which is what the `pos` out-parameter receives.
pub fn stoi_with_pos(s: &str) -> Result<(i32, usize), StoiError> {
    let bytes = s.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_space(bytes[index]) {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(b'-') => {
            index += 1;
            true
        }
        Some(b'+') => {
            index += 1;
            false
        }
        _ => false,
    };

    let digits_start = index;
    // Accumulate in i64 and latch overflow: the digit run may be arbitrarily
    // long, and strtol still consumes all of it before reporting ERANGE.
    let mut magnitude: i64 = 0;
    let mut overflowed = false;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        if !overflowed {
            magnitude = magnitude * 10 + i64::from(bytes[index] - b'0');
            // i32::MIN's magnitude is one larger than i32::MAX's.
            if magnitude > i64::from(i32::MAX) + 1 {
                overflowed = true;
            }
        }
        index += 1;
    }

    if index == digits_start {
        return Err(StoiError::InvalidArgument);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        return Err(StoiError::OutOfRange);
    }

    Ok((value as i32, index))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_like_the_c_library() {
        assert_eq!(stoi("0"), Ok(0));
        assert_eq!(stoi("5"), Ok(5));
        assert_eq!(stoi("-5"), Ok(-5));
        assert_eq!(stoi("+3"), Ok(3));
        assert_eq!(stoi(" 7"), Ok(7));
        assert_eq!(stoi("\t\n 42"), Ok(42));
        assert_eq!(stoi("12abc"), Ok(12));
        assert_eq!(stoi("3.9"), Ok(3));
        assert_eq!(stoi("0x10"), Ok(0));
        assert_eq!(stoi("007"), Ok(7));
        assert_eq!(stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(stoi("-2147483648"), Ok(i32::MIN));
    }

    #[test]
    fn reports_the_same_exceptions() {
        assert_eq!(stoi(""), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("abc"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("   "), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("+"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("- 1"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("99999999999999999999"), Err(StoiError::OutOfRange));
    }

    #[test]
    fn reports_consumed_length() {
        assert_eq!(stoi_with_pos("  12abc"), Ok((12, 4)));
        assert_eq!(stoi_with_pos("-8"), Ok((-8, 2)));
    }
}

