//! Rust port of `tests/test5.cpp` from the hopscotch-map test suite.
//!
//! ```text
//! test5 [--a COUNT]
//! ```
//!
//! Fills a hopscotch map with `COUNT` (default 5) entries `i -> i * 2`, erases
//! every even key, then prints the surviving size and the number of erasures.
//!
//! The map itself, the `std::stoi` argument parsing and the C++ termination
//! behaviour on a bad argument are all re-implemented on top of `std` alone —
//! see the modules under `src/`.

// The crate root lives in the package root while the library modules live in
// `src/`, so each top-level module needs an explicit path. This keeps a plain
// `rustc test5.rs` working alongside `cargo build --release`.
#[path = "src/cpp/mod.rs"]
mod cpp;
#[path = "src/hash.rs"]
mod hash;
#[path = "src/hopscotch/mod.rs"]
mod hopscotch;

use cpp::{stoi, terminate_with};
use hopscotch::HopscotchMap;

fn main() {
    let argv: Vec<String> = std::env::args().collect();

    let mut count: i32 = 5;
    if argv.len() > 1 && argv[1] == "--a" {
        // The C++ code indexes `argv[2]` unconditionally here. When it is
        // absent that is a null pointer handed to `std::string`, which throws
        // `std::logic_error` and terminates the process.
        let raw = match argv.get(2) {
            Some(raw) => raw,
            None => terminate_with("std::logic_error", "basic_string::_S_construct null not valid"),
        };
        count = match stoi(raw) {
            Ok(value) => value,
            Err(error) => terminate_with(error.exception_type(), error.what()),
        };
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    let mut i: i32 = 0;
    while i < count {
        map.insert(i, i.wrapping_mul(2));
        i += 1;
    }

    let mut removed: i32 = 0;
    let mut i: i32 = 0;
    while i < count {
        removed += map.erase(&i) as i32;
        i = i.wrapping_add(2);
    }

    println!("{} {}", map.len(), removed);
}

