        // The C++ code indexes `argv[2]` unconditionally here. When it is
        // absent that is a null pointer handed to `std::string`, which throws
        // `std::logic_error` and terminates the process.
        let raw = match argv.get(2) {
            Some(raw) => raw,
            None => terminate_with("std::logic_error", "basic_string::_S_construct null not valid"),
        };
        count = match stoi(raw) {
            Ok(value) => value,
            Err(error) => terminate_with(error.exception_type(), error.what()),
        };
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    let mut i: i32 = 0;
    while i < count {
        map.insert(i, i.wrapping_mul(2));
        i += 1;
    }

    let mut removed: i32 = 0;
    let mut i: i32 = 0;
    while i < count {
        removed += map.erase(&i) as i32;
